/*
 * 01-item.js — item CRUD against a live VES vault.
 * JS mirror of libVES.c/tests/01-item.
 *
 * t.ves is opened on a SECONDARY vault (domain + externalId). Items get
 * stored in that same vault — no separate vault lookup needed.
 *
 * Requires t.conf.DOM and t.conf.EMAIL (used as externalId); t.conf.OBJ is
 * generated by vestest.fillConf() if not pre-set.
 *
 * Runs as `node tests/01-item.js` or loaded via <script> in index.html.
 */

if (typeof window === 'undefined' && typeof require !== 'undefined') require('./node.inc.js');

vestest.register('01-item', async function (t) {
    var ref = libVES.Vault.toRef(t.conf.OBJ);
    var vault = new libVES.Vault({ domain: t.conf.DOM, externalId: t.conf.EMAIL }, t.ves);

    t.head('Checking app vault //' + t.conf.DOM + '/' + t.conf.EMAIL);
    await t.run('vault accessible', async function () {
        await vault.entries();
    });

    t.head('Creating item ' + t.conf.OBJ + ' with a value "test"');
    await t.run('put item', async function () {
        await vault.item(ref).put('test');
    });

    t.head('Retrieving the value of ' + t.conf.OBJ);
    var got;
    await t.run('get item', async function () { got = await vault.item(ref).get(); });
    await t.expect('value is "test"', 'test', got);

    t.head('Overwriting item ' + t.conf.OBJ + ' with a value "another test"');
    await t.run('put item again', async function () {
        await vault.item(ref).put('another test');
    });

    t.head('Retrieving the value of ' + t.conf.OBJ);
    await t.run('get item', async function () { got = await vault.item(ref).get(); });
    await t.expect('value is "another test"', 'another test', got);

    t.head('Setting plaintext metadata on ' + t.conf.OBJ);
    await t.run('put meta', async function () {
        var item = vault.item(ref);
        await item._entries();
        await item.vaultItem.setField('meta', { test: 1234 });
        await item.vaultItem.post();
    });

    t.head('Retrieving plaintext metadata on ' + t.conf.OBJ);
    var meta;
    await t.run('get meta', async function () {
        var item = vault.item(ref);
        await item._entries();
        meta = await item.vaultItem.getMeta();
    });
    await t.expect('meta JSON', '{"test":1234}', JSON.stringify(meta));

    t.head('Deleting ' + t.conf.OBJ);
    await t.run('delete item', async function () {
        await vault.item(ref).delete();
    });

    t.head('Retrieving the value of ' + t.conf.OBJ + ' - error expected');
    await t.run('get deleted item rejects', async function () {
        var threw = null;
        try { await vault.item(ref).get(); } catch (e) { threw = e; }
        if (!threw) throw new Error('expected an error, got value');
    });

    t.head('Creating item ' + t.conf.OBJ + ' again with a value "yet another test"');
    await t.run('put item', async function () {
        await vault.item(ref).put('yet another test');
    });

    t.head('Retrieving the value of ' + t.conf.OBJ);
    await t.run('get item', async function () { got = await vault.item(ref).get(); });
    await t.expect('value is "yet another test"', 'yet another test', got);

    t.head('Deleting ' + t.conf.OBJ);
    await t.run('delete item', async function () {
        await vault.item(ref).delete();
    });
});

if (typeof require !== 'undefined' && require.main === module) vestest.runFromNode(['01-item']);
